    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/situations/2"],
      "relevance": "'결과가 확실해질 때까지 계속 고치거나 상업적인 일만 해야 한다'는 규칙이 파일 이름·색감을 끝없이 고치며 제출을 미룬 행동의 내적 규칙으로 작동함. 상담사의 질문은 이 규칙이 미룸으로 기능하고 있음을 내담자가 자각하는지 탐구하는 것."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": ["/situations/2"],
      "relevance": "'완성도를 계속 높이고 공개를 미룬다면 부족한 결과로 평가받는 일을 피할 수 있다'는 가정은 미룸의 동기. 상담사가 '미루고 있었던 것'이라고 명명할 때 이 가정이 작동하고 있음을 가리킴."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/situations/2"],
      "relevance": "'온 힘을 다해 내놓았는데 반응이 없으면 변명할 수 없이 실패한 사람이 증명된다'는 두려움이 미룸의 이면에 있음. 상담사의 질문이 이 두려움을 자각하게 하려는 의도를 포함."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "'진짜로 도전하면 평범하고 무능한 사람이라는 것이 드러날 것'이라는 핵심 신념이 파일 이름·색감 고치기를 통해 도전 자체를 회피하는 근본 이유. 성장 경험에서 아버지의 반응과 친척의 조롱이 이 신념의 형성 맥락."
    },
    {
      "trait_id": "/coping_strategies/3",
      "background_ids": [],
      "relevance": "내담자가 '상업 촬영 일정만 계속 늘리고 있다'고 말한 부분은 상업 촬영을 바쁜 상태의 근거로 삼아 개인 작업 미룸을 정당화하는 전략에 해당. 상담사의 질문 맥락에서 미룸의 또 다른 양상으로 연결됨."
    }
  ]
}

